<article class="product-card"><a class="product-image" href="<?php echo e(route('product.show',$product)); ?>"><?php if($product->image): ?><img src="<?php echo e(Storage::url($product->image)); ?>" alt="<?php echo e($product->name); ?>" loading="lazy"><?php else: ?><div class="product-placeholder tone-<?php echo e($product->id % 4); ?>"><span><?php echo e(strtoupper(substr($product->name,0,1))); ?></span></div><?php endif; ?>
<?php if($product->discount_percent): ?><span class="sale-tag">-<?php echo e($product->discount_percent); ?>%</span><?php elseif($product->is_featured): ?><span class="new-tag">FEATURED</span><?php endif; ?></a><div class="product-info"><a class="product-category" href="<?php echo e(route('category.show',$product->category)); ?>"><?php echo e($product->category->name); ?></a><h3><a href="<?php echo e(route('product.show',$product)); ?>"><?php echo e($product->name); ?></a></h3><div class="price">₹<?php echo e(number_format($product->price,2)); ?> <?php if($product->compare_price): ?><del>₹<?php echo e(number_format($product->compare_price,2)); ?></del><?php endif; ?></div><form action="<?php echo e(route('cart.add',$product)); ?>" method="POST"><?php echo csrf_field(); ?><input type="hidden" name="quantity" value="1"><button class="quick-add" <?php echo e($product->stock < 1 ? 'disabled' : ''); ?>><?php echo e($product->stock < 1 ? 'Sold out' : 'Add to bag +'); ?></button></form></div></article>
